import { headers } from "next/headers";
import { auth, DB_PATH } from "./auth";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type UserRow = {
  id: string;
  email: string;
  name: string | null;
  createdAt: string | number;
};

// Reuse one connection across calls (module scope survives across requests
// in the Next.js server runtime) instead of opening a handle per query.
declare global {
  // eslint-disable-next-line no-var
  var __notelyDb: Database.Database | undefined;
}

function getDb() {
  if (!global.__notelyDb) {
    global.__notelyDb = new Database(DB_PATH);
  }
  return global.__notelyDb;
}

function toUser(row: UserRow): User {
  return {
    id: row.id,
    email: row.email,
    name: row.name ?? row.email,
    createdAt: new Date(row.createdAt).toISOString(),
  };
}

// These read straight from the `user` table that Better Auth (src/lib/auth.ts)
// creates and manages — sign up/sign in there is what populates it.
export async function listUsers(): Promise<User[]> {
  const rows = getDb()
    .prepare(`SELECT id, email, name, createdAt FROM user ORDER BY createdAt ASC`)
    .all() as UserRow[];
  return rows.map(toUser);
}

export async function getUser(id: string): Promise<User | undefined> {
  const row = getDb()
    .prepare(`SELECT id, email, name, createdAt FROM user WHERE id = ?`)
    .get(id) as UserRow | undefined;
  return row ? toUser(row) : undefined;
}

export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth.api.getSession({ headers: await headers() });
  if (!session?.user) return undefined;
  return getUser(session.user.id);
}

